create role anon; create role authenticated;
create table members(id text primary key,name text,role text,instrument text,avatar text,color text,status text,is_admin boolean,pin text,vocal_category text);
create table songs(id text primary key,title text,artist text,cat text,key text,bpm integer,time_signature text,tags text[],yturl text,media_url text,lyrics text,vocal_keys jsonb default '{}',created_by text,delete_requested_by text,featured_week boolean,featured_note text);
create table events(id text primary key,date text,time text,type text,label text,theme text,santa_ceia_song text,delete_requested_by text);
create table event_songs(id bigint generated by default as identity primary key,event_id text,song_id text,item_type text,note_text text,order_index integer,singer_member_id text,sequence text);
create table event_members(id bigint generated by default as identity primary key,event_id text,member_id text,confirmed boolean,unique(event_id,member_id));
create table equipment(id text primary key,name text,brand text,status text,custodian_id text,serial_number text);
create table announcements(id text primary key,title text,content text,created_by text,created_at timestamptz default clock_timestamp());
create table announcement_comments(id text primary key,post_id text,member_id text,member_name text,text text,created_at timestamptz default clock_timestamp());
create table announcement_reactions(id bigint generated by default as identity primary key,post_id text,member_id text,emoji text);
create table announcement_saves(id bigint generated by default as identity primary key,post_id text,member_id text);
create table rehearsal_sessions(event_id text primary key,active_song_id text,style_mode text,timer_active boolean,timer_seconds integer);
create table rehearsal_notes(song_id text primary key,note_text text,updated_by text);
create table rehearsal_takes(id text primary key,event_id text,name text,url text,created_at timestamptz default clock_timestamp());
grant usage,select on all sequences in schema public to anon,authenticated;
